import React, { useState, useEffect } from "react";
import "./Footer.css";
import { Fade } from "react-reveal";
import { greeting } from "../../portfolio.js";

export default function Footer(props) {
  const [visitedCount, setVisitedCount] = useState("Loading...");
  
  useEffect(() => {
    // Initialize CounterAPI for visitor tracking
    const initializeCounter = async () => {
      try {
        // Use CounterAPI with your workspace and API key
        const response = await fetch('https://api.counterapi.dev/v1/brayton-portfolio/visits-brayton-portfolio/up', {
          method: 'GET',
        });
        
        if (response.ok) {
          const data = await response.json();
          console.log('CounterAPI response:', data);
          setVisitedCount(data.count);
        } else {
          console.error('CounterAPI failed with status:', response.status);
          setVisitedCount('Error');
        }
      } catch (error) {
        console.error('Counter API error:', error);
        setVisitedCount('Error');
      }
    };
    
    initializeCounter();
  }, []);

  return (
    <div className="footer-div">
      <Fade>
        <p className="footer-text" style={{ color: props.theme.secondaryText }}>
          Made with <span role="img">❤️</span> by {greeting.title}
          <br />
          Since July 2025, I have been visited {visitedCount - 17} times.
        </p>
        <p className="footer-text">
          <br />
          Website Last Updated: {greeting.websiteLastUpdated}
          <br />
          Previously: {greeting.websitePreviouslyUpdated}
        </p>
      </Fade>
    </div>
  );
}
